changeSet.sql:
INSERT INTO sub_modules (name, code, module_id, enabled)
SELECT 'Pagos y aplicaciones de suscripcion', 'SUBSCRIPTION_PAYMENT', (SELECT id FROM modules WHERE code = 'GENERAL'), 1
WHERE NOT EXISTS (SELECT 1 FROM sub_modules WHERE code = 'SUBSCRIPTION_PAYMENT');

INSERT INTO sub_modules (name, code, module_id, enabled)
SELECT 'Cobranza de suscripcion', 'DUNNING', (SELECT id FROM modules WHERE code = 'GENERAL'), 1
WHERE NOT EXISTS (SELECT 1 FROM sub_modules WHERE code = 'DUNNING');

INSERT INTO base_permissions (name, code, sub_module_id, enabled)
SELECT 'Ver pagos de suscripcion', 'subscriptionPayment.read', (SELECT id FROM sub_modules WHERE code = 'SUBSCRIPTION_PAYMENT'), 1
WHERE NOT EXISTS (SELECT 1 FROM base_permissions WHERE code = 'subscriptionPayment.read');

INSERT INTO base_permissions (name, code, sub_module_id, enabled)
SELECT 'Ver aplicaciones de pago', 'billingDocumentApplication.read', (SELECT id FROM sub_modules WHERE code = 'SUBSCRIPTION_PAYMENT'), 1
WHERE NOT EXISTS (SELECT 1 FROM base_permissions WHERE code = 'billingDocumentApplication.read');

INSERT INTO base_permissions (name, code, sub_module_id, enabled)
SELECT 'Ver expediente de cobranza', 'dunningEvent.read', (SELECT id FROM sub_modules WHERE code = 'DUNNING'), 1
WHERE NOT EXISTS (SELECT 1 FROM base_permissions WHERE code = 'dunningEvent.read');

changeSet.rollback:
DELETE FROM base_role_permissions
WHERE base_permission_id IN (
    SELECT id FROM base_permissions WHERE code = 'dunningEvent.read');
